  1→//! Debug shell for step failure investigation.
  2→//!
  3→//! Spawns an interactive shell with the step's environment for debugging
  4→//! when a step fails during `bivvy run`.
  5→
  6→use std::collections::HashMap;
  7→use std::path::Path;
  8→use std::process::Command;
  9→
 10→use crate::error::Result;
 11→use crate::shell::platform::detect_shell;
 12→
 13→/// Spawn an interactive debug shell for investigating a step failure.
 14→///
 15→/// The shell inherits stdin/stdout/stderr (takes over the terminal) and
 16→/// blocks until the user exits. Sets `BIVVY_DEBUG=1` and
 17→/// `BIVVY_DEBUG_STEP=<step_name>` in the environment.
 18→pub fn spawn_debug_shell(
 19→    step_name: &str,
 20→    project_root: &Path,
 21→    step_env: &HashMap<String, String>,
 22→    global_env: &HashMap<String, String>,
 23→) -> Result<()> {
 24→    let shell_info = detect_shell();
 25→    let shell_exe = shell_info.executable;
 26→
 27→    let mut cmd = Command::new(&shell_exe);
 28→    cmd.arg("-i"); // Interactive — loads user's dotfiles
 29→
 30→    // Set working directory
 31→    cmd.current_dir(project_root);
 32→
 33→    // Merge global env + step env (step overrides global)
 34→    let mut env: HashMap<String, String> = global_env.clone();
 35→    env.extend(step_env.iter().map(|(k, v)| (k.clone(), v.clone())));
 36→
 37→    // Add bivvy debug markers
 38→    env.insert("BIVVY_DEBUG".to_string(), "1".to_string());
 39→    env.insert("BIVVY_DEBUG_STEP".to_string(), step_name.to_string());
 40→
 41→    cmd.envs(&env);
 42→
 43→    // Inherit stdio (takes over terminal)
 44→    cmd.stdin(std::process::Stdio::inherit());
 45→    cmd.stdout(std::process::Stdio::inherit());
 46→    cmd.stderr(std::process::Stdio::inherit());
 47→
 48→    // Spawn and wait
 49→    let mut child = cmd
