import re, os
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()
        # Remove test modules
        # Simple approach: find lines with .unwrap() outside #[cfg(test)] blocks
        in_test = False
        brace_depth = 0
        for i, line in enumerate(content.split('\n'), 1):
            if '#[cfg(test)]' in line:
                in_test = True
                continue
            if in_test:
                brace_depth += line.count('{') - line.count('}')
                if brace_depth <= 0 and '{' not in line and '}' in line:
                    in_test = False
                    brace_depth = 0
                continue
            if '.unwrap()' in line:
                print(f'{path}:{i}: {line.strip()}')
"

