            format!(
                "{} {}",
                theme.step_number.apply_to(&step_number),
                theme.step_title.apply_to(step_name)
            )
        } else {
            format!(
                "{} {} {} {}",
                theme.step_number.apply_to(&step_number),
                theme.step_title.apply_to(step_name),
                theme.dim.apply_to("—"),
                theme.dim.apply_to(&step.title)
