python3 -c "
import re, os, sys

# Find all .rs files, exclude test code, find .unwrap() calls
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()
        in_test = False
        brace_depth = 0
        for i, line in enumerate(lines):
            stripped = line.strip()
            if '#[cfg(test)]' in stripped:
                in_test = True
            if in_test:
                brace_depth += line.count('{') - line.count('}')
                if brace_depth <= 0 and i > 0:
                    in_test = False
                    brace_depth = 0
                continue
            if '.unwrap()' in line:
                print(f'{path}:{i+1}: {line.rstrip()}')
"

