python3 -c "
import re, os, sys

# More reliable approach: track #[cfg(test)] mod blocks properly
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()
            lines = content.split('\n')

        # Find test module boundaries
        test_ranges = []
        i = 0
        while i < len(lines):
            if '#[cfg(test)]' in lines[i]:
                # Find the mod block that follows
                j = i + 1
                while j < len(lines) and 'mod ' not in lines[j] and '{' not in lines[j]:
                    j += 1
                if j < len(lines):
                    # Count braces to find end
                    depth = 0
                    start = j
                    for k in range(j, len(lines)):
                        depth += lines[k].count('{') - lines[k].count('}')
                        if depth <= 0 and k > j:
                            test_ranges.append((i, k))
                            break
                    else:
                        test_ranges.append((i, len(lines)))
            i += 1

        # Check each line with .unwrap() that's NOT in a test range
        for lineno, line in enumerate(lines):
            if '.unwrap()' not in line:
                continue
            in_test = False
            for start, end in test_ranges:
                if start <= lineno <= end:
                    in_test = True
                    break
            if not in_test and not line.strip().startswith('//'):
                print(f'{path}:{lineno+1}: {line.rstrip()}')
" 2>&1 | grep -v '//!' | head -80

